ALTER TABLE "learning_events" DROP CONSTRAINT "event_contract";--> statement-breakpoint
ALTER TABLE "learning_events" ADD CONSTRAINT "event_contract" CHECK (("learning_events"."type" = 'attempt_started' AND "learning_events"."sequence" = 1 AND "learning_events"."payload" = '{}'::jsonb) OR ("learning_events"."sequence" > 1 AND (("learning_events"."type" IN ('hint_requested','attempt_completed','attempt_abandoned') AND "learning_events"."payload" = '{}'::jsonb) OR ("learning_events"."type" = 'answer_submitted' AND coalesce(jsonb_typeof("learning_events"."payload"->'correct'), '') = 'boolean' AND "learning_events"."payload" - 'correct' = '{}'::jsonb))));